import Link from "next/link";
import { ACCESS_REPORTS, ACCESS_REPORTS_IMPORTED_ON } from "@/data/accessReports";
import { ACCEPT_LABEL, MEDIAN_MIN, REPO, buildIssueUrl, scoreboard } from "@/lib/accessReportSubmission.mjs";

/**
 * The all-vendor access scoreboard on the /integrate hub: per vendor, the
 * accepted access reports (src/data/accessReports.ts, generated by
 * scripts/import-access-reports.mjs), the count per outcome and the median
 * days to a first answer, computed by scoreboard() in
 * src/lib/accessReportSubmission.mjs with the vendor panel's own rule (the
 * median only once MEDIAN_MIN reports give a number). Each row links the
 * vendor's panel (components/AccessReports) on its English /integrate page.
 *
 * It sits on /integrate rather than /pricing because every vendor a report can
 * name has an /integrate guide and its panel lives there: the scoreboard is
 * the index of those panels. With no accepted report it says so and offers the
 * prefilled issue with no vendor chosen.
 */

const linkCls = "font-medium text-brand-600 hover:text-brand-500";

export default function AccessScoreboard() {
  const rows = scoreboard(ACCESS_REPORTS);
  const total = rows.reduce((n, r) => n + r.total, 0);
  const days = (n: number) => `${n} ${n === 1 ? "day" : "days"}`;
  const cell = (n: number) => (n === 0 ? <span className="text-[var(--muted)]">0</span> : n);

  return (
    <section id="access-scoreboard" data-access-scoreboard={total} className="mt-14 scroll-mt-24">
      <h2 className="text-2xl font-bold tracking-tight text-[var(--fg)]">API access: reports from developers, by vendor</h2>
      <p className="mt-2 text-sm leading-relaxed text-[var(--muted)]">
        {`No vendor here publishes how long an access application takes to answer or how often one is refused, so these are developers' own accounts: one public GitHub issue each in this site's repository (${REPO}), counted once a maintainer has read it and added the `}
        <code className="font-mono text-xs">{ACCEPT_LABEL}</code>
        {` label. The median is shown once ${MEDIAN_MIN} reports for a vendor give a number of days. A report is one submitter's account, not a figure from the vendor.`}
      </p>

      {total === 0 && (
        <div data-access-scoreboard-empty className="mt-5 rounded-2xl border border-brand-400/30 bg-brand-500/5 p-5">
          <p className="text-sm font-semibold text-[var(--fg)]">No report has been accepted yet, for any vendor.</p>
          <p className="mt-1 text-sm text-[var(--muted)]">
            {"If you have applied for Garmin, WHOOP, Oura, Strava, Dexcom or any vendor below, the first report fills a row. The button opens a GitHub issue with the form; everything in it is public, so leave out keys, emails and people's names."}
          </p>
          <a
            href={buildIssueUrl()}
            rel="noopener"
            data-cta="access-report-any"
            data-cta-source="access-scoreboard"
            className="mt-4 inline-flex min-h-[40px] items-center rounded-xl bg-brand-600 px-5 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-500"
          >
            Report your application
          </a>
        </div>
      )}

      <div className="mt-5 overflow-x-auto">
        <table className="w-full min-w-[560px] text-left text-sm">
          <thead className="text-xs uppercase tracking-wider text-[var(--muted)]">
            <tr>
              <th className="py-2 pr-3">Vendor</th>
              <th className="py-2 pr-3 text-right">Reports</th>
              <th className="py-2 pr-3 text-right">Approved</th>
              <th className="py-2 pr-3 text-right">Rejected</th>
              <th className="py-2 pr-3 text-right">No answer</th>
              <th className="py-2 pr-3 text-right">Pending</th>
              <th className="py-2 text-right">Median days to first answer</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.slug} data-access-scoreboard-row={`${r.slug}:${r.total}`} className="border-t border-[var(--border)] text-[var(--fg)]">
                <td className="py-2 pr-3">
                  <Link href={`${r.page}#access-reports`} className={linkCls}>
                    {r.name}
                  </Link>
                </td>
                <td className="py-2 pr-3 text-right font-mono">{cell(r.total)}</td>
                <td className="py-2 pr-3 text-right font-mono">{cell(r.counts.approved)}</td>
                <td className="py-2 pr-3 text-right font-mono">{cell(r.counts.rejected)}</td>
                <td className="py-2 pr-3 text-right font-mono">{cell(r.counts["no-answer"])}</td>
                <td className="py-2 pr-3 text-right font-mono">{cell(r.counts.pending)}</td>
                <td className="py-2 text-right font-mono">
                  {r.medianDays !== null ? (
                    days(r.medianDays)
                  ) : (
                    <span className="text-[var(--muted)]" title={`Shown once ${MEDIAN_MIN} reports give a number of days (${r.withDays} so far)`}>
                      {`— (${r.withDays}/${MEDIAN_MIN})`}
                    </span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="mt-3 text-xs text-[var(--muted)]">
        {ACCESS_REPORTS_IMPORTED_ON ? `Imported ${ACCESS_REPORTS_IMPORTED_ON}. ` : ""}
        {"Each vendor's row links its panel, with every report and a link to its issue. A README badge per vendor, redrawn at each import: "}
        <Link href="/badges#access-badges" className={linkCls}>
          access-report badges
        </Link>
        .
      </p>
    </section>
  );
}
